// Pack snapshots are generated by the same target and checked without weakening sandbox imports.
import assert from 'node:assert/strict';
import { cpSync, copyFileSync, symlinkSync, mkdtempSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import * as vocabulary from '../contracts/generated/vocabulary.ts';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { test } from 'node:test';
import { drift, packVocabularyFiles, write } from './gen-contracts.ts';

test('pack vocabulary targets contain only their required axes and deterministic generated bytes', async () => {
  const root = fileURLToPath(new URL('../', import.meta.url));
  const files = packVocabularyFiles(root);
  assert.equal(Object.keys(files).length, 2);
  for (const [path, text] of Object.entries(files)) {
    assert.match(text, /^\/\/ 生成物，勿手改/);
    const snapshot = await import(pathToFileURL(join(root, path)).href);
    for (const name of Object.keys(snapshot)) assert.deepEqual(snapshot[name], vocabulary[name as keyof typeof vocabulary]);
    if (path.includes('regression-scope') || path.includes('maintenance-sweep')) {
      assert.match(text, /export const ENTRY_KIND =/);
      assert.match(text, /export const CHANGE_KIND =/);
      assert.ok(!text.includes('export const MEASURE ='));
    } else {
      assert.match(text, /export const MEASURE =/);
      assert.ok(!text.includes('export const ENTRY_KIND ='));
    }
  }
  assert.deepEqual(files, packVocabularyFiles(root));
});

test('the generator detects missing, edited and model-stale pack snapshots and repairs them', t => {
  const root = mkdtempSync(join(tmpdir(), 'circle-hub-pack-vocabulary-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  mkdirSync(join(root, 'contracts'), { recursive: true });
  const source = JSON.parse(readFileSync(new URL('../contracts/model.json', import.meta.url), 'utf8'));
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  const expected = packVocabularyFiles(root);
  assert.equal(drift(root, {}, expected).length, 2);
  write(root, {}, expected);
  assert.deepEqual(drift(root, {}, expected), []);
  const first = Object.keys(expected)[0];
  writeFileSync(join(root, first), expected[first] + '// changed\n');
  assert.ok(drift(root, {}, expected).some(p => p.includes(first)));
  write(root, {}, expected);
  source.vocabulary.find((a: { axis: string }) => a.axis === 'measure').values.push({ code: 'synthetic_added', label: '合成新增' });
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  const unchanged = packVocabularyFiles(root);
  assert.deepEqual(unchanged, expected, 'measure changes must not rewrite ID-range consumers');
  source.vocabulary.find((a: { axis: string }) => a.axis === 'change_kind').values.push({ code: 'synthetic_change', label: '合成变更' });
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  const updated = packVocabularyFiles(root);
  assert.equal(drift(root, {}, updated).length, 2);
  write(root, {}, updated);
  assert.deepEqual(drift(root, {}, updated), []);
  assert.ok(readFileSync(join(root, first), 'utf8').includes('生成物，勿手改'));
});


test('the CLI --check includes every pack snapshot in its drift verdict', t => {
  const root = mkdtempSync(join(tmpdir(), 'circle-hub-pack-vocabulary-cli-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const repo = fileURLToPath(new URL('../', import.meta.url));
  cpSync(join(repo, 'contracts'), join(root, 'contracts'), { recursive: true });
  mkdirSync(join(root, 'tools'));
  copyFileSync(join(repo, 'tools/gen-contracts.ts'), join(root, 'tools/gen-contracts.ts'));
  symlinkSync(join(repo, 'node_modules'), join(root, 'node_modules'), 'dir');
  const run = (...args: string[]) => spawnSync(process.execPath, [join(root, 'tools/gen-contracts.ts'), ...args], { encoding: 'utf8', cwd: root });
  assert.equal(run().status, 0);
  assert.equal(run('--check').status, 0);
  const files = packVocabularyFiles(root);
  for (const [path, content] of Object.entries(files)) {
    writeFileSync(join(root, path), content + '// drift\n');
    const drifted = run('--check');
    assert.equal(drifted.status, 1);
    assert.ok(drifted.stderr.includes(path), drifted.stderr);
    writeFileSync(join(root, path), content);
  }
  assert.equal(run('--check').status, 0);
});
